14	// 本文件是“已保存的成功关闭请求的返回结果必须与原请求所指的已关闭批次一致”
15	// 的回归保障：批次用请求编号关闭后，按原编号、原内容再次提交 CloseBatch，
16	// 只能取回第一次关闭时确认的完整批次结果。台账里保存的关闭结果即使变成
17	// null、空对象，或被改成另一批次的结果、被改掉配方绑定/份数/投料/核对差额，
18	// 也不能被当作成功结果返回——打开台账及之后的每次查询/写入重载，都必须
19	// 核对保存结果与原请求所指批次（必须存在并仍为已关闭）的实际记录一致；
20	// 不一致按 ErrCorruptData 拒绝整份台账，不删除请求、不重做关闭，也不用
21	// 当前查询结果覆盖损坏结果。
22	
23	// setupCloseRequestLedger 在 dir 建立一份正常台账并关闭：
24	//   - B1（已关闭）：RC/v1、3 份，按 wantCloseFeedings 登记三条投料
25	//     （f1、f2、f3），close-b1 关闭；
26	//   - B2（已关闭）：与 B1 相同的配方、份数与投料内容（f1-b2 等），
27	//     close-b2 关闭——其保存结果与 B1 的仅批次编号不同，用于验证
28	//     另一批次的结果不能顶替；
29	//   - B3（执行中）：RC/v1、2 份，无投料的正常批次，用于验证损坏的
30	//     关闭请求不能被“本次访问的是另一个正常批次”绕过。
31	//
32	// 返回落盘后的台账文件内容，供各用例改坏后重写。
33	func setupCloseRequestLedger(t *testing.T, dir string) []byte {
34		t.Helper()
35		s, err := Open(dir)
36		if err != nil {
37			t.Fatalf("Open 失败: %v", err)
38		}
39		registerCloseRecipe(t, s) // RC/v1：M1=0.1、M2=0.2
40		if _, err := s.CreateBatch("b1", "B1", "RC", "v1", 3); err != nil {
41			t.Fatal(err)
42		}
43		if _, err := s.StartBatch("start-b1", "B1"); err != nil {
44			t.Fatal(err)
45		}
46		for i, want := range wantCloseFeedings() {
47			reqNo := []string{"f1", "f2", "f3"}[i]
48			if _, err := s.AddFeeding(reqNo, "B1", want.MaterialNo, want.Grams, want.Time, want.Registrar); err != nil {
49				t.Fatal(err)
50			}
51		}
52		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
53			t.Fatal(err)
54		}
55		// B2：配方、份数、投料内容与 B1 完全相同，仅批次编号与请求编号不同。
56		if _, err := s.CreateBatch("b2", "B2", "RC", "v1", 3); err != nil {
57			t.Fatal(err)
58		}
59		if _, err := s.StartBatch("start-b2", "B2"); err != nil {
60			t.Fatal(err)
61		}
62		for i, want := range wantCloseFeedings() {
63			reqNo := []string{"f1-b2", "f2-b2", "f3-b2"}[i]
64			if _, err := s.AddFeeding(reqNo, "B2", want.MaterialNo, want.Grams, want.Time, want.Registrar); err != nil {
65				t.Fatal(err)
66			}
67		}
68		if _, err := s.CloseBatch("close-b2", "B2"); err != nil {
69			t.Fatal(err)
70		}
71		// B3：执行中、无投料的正常批次。
72		if _, err := s.CreateBatch("b3", "B3", "RC", "v1", 2); err != nil {
73			t.Fatal(err)
74		}
75		if _, err := s.StartBatch("start-b3", "B3"); err != nil {
76			t.Fatal(err)
77		}
78		if err := s.Close(); err != nil {
79			t.Fatal(err)
80		}
81		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
82		if err != nil {
83			t.Fatal(err)
84		}
85		return good
86	}
87	
88	// closeResultRaw 取出正常台账中 reqNo 请求的保存结果原文。
89	func closeResultRaw(t *testing.T, good []byte, reqNo string) json.RawMessage {
90		t.Helper()
91		var st persistedState
92		if err := json.Unmarshal(good, &st); err != nil {
93			t.Fatal(err)
94		}
95		req := st.Requests[reqNo]
96		if req == nil {
97			t.Fatalf("正常台账中应存在 %s 请求记录", reqNo)
98		}
99		return req.Result
100	}
101	
102	// mutatedCloseView 读出 close-b1 的保存结果，按 edit 修改后重新序列化。
103	func mutatedCloseView(t *testing.T, good []byte, edit func(*BatchView)) json.RawMessage {
104		t.Helper()
105		var v BatchView
106		if err := json.Unmarshal(closeResultRaw(t, good, "close-b1"), &v); err != nil {
107			t.Fatal(err)
108		}
109		edit(&v)
110		raw, err := json.Marshal(v)
111		if err != nil {
112			t.Fatal(err)
113		}
114		return raw
115	}
116	
117	// corruptCloseRequestResult 把正常台账内容中 close-b1 请求的保存结果替换为
118	// mutate 给出的值（mutate 返回 nil 表示删除该字段），返回改写后的文件内容。
119	func corruptCloseRequestResult(t *testing.T, good []byte, mutate func() json.RawMessage) []byte {
120		t.Helper()
121		var st persistedState
122		if err := json.Unmarshal(good, &st); err != nil {
123			t.Fatal(err)
124		}
125		req := st.Requests["close-b1"]
126		if req == nil {
127			t.Fatalf("正常台账中应存在 close-b1 请求记录")
128		}
129		req.Result = mutate()
130		data, err := json.MarshalIndent(&st, "", "  ")
131		if err != nil {
132			t.Fatal(err)
133		}
134		return data
135	}
