// 返回首次关闭成功的结果与落盘后的台账文件内容，供各用例改坏后重写。
func setupLimitCloseLedger(t *testing.T, dir string, feedMilli bool) (*BatchView, []byte) {
	t.Helper()
	s, err := Open(dir)
	if err != nil {
		t.Fatalf("Open 失败: %v", err)
